/**
 * frontend/src/auth_service.js - VERSION COMPLÈTE ET À JOUR
 * À REMPLACER le fichier existant
 * Gère l'authentification JWT complète
 */

import api, { setAuthToken, clearAuthToken } from './api_service';

const ACCESS_TOKEN_KEY = 'access_token';
const REFRESH_TOKEN_KEY = 'refresh_token';
const USER_KEY = 'user';

class AuthService {
  /**
   * ============ LOGIN ============
   * Authentifie l'utilisateur avec credentials
   * @param {string} username
   * @param {string} password
   * @returns {Promise<{success: boolean, user?: object, error?: string}>}
   */
  async login(username, password) {
    try {
      console.log('🔐 [AUTH] Login attempt:', { username });

      const response = await api.post('/auth/login/', {
        username,
        password
      });

      console.log('✅ [AUTH] Login successful!', response.data);

      const { access, refresh, user } = response.data;

      // Stocker les tokens
      localStorage.setItem(ACCESS_TOKEN_KEY, access);
      localStorage.setItem(REFRESH_TOKEN_KEY, refresh);
      localStorage.setItem(USER_KEY, JSON.stringify(user));

      // Définir le header d'autorisation
      setAuthToken(access);

      return { 
        success: true, 
        user 
      };
    } catch (error) {
      const errorMsg = error.response?.data?.error || 
                       error.response?.data?.message || 
                       error.message || 
                       'Login failed';

      console.error('❌ [AUTH] Login failed:', errorMsg);

      return {
        success: false,
        error: errorMsg
      };
    }
  }

  /**
   * ============ REGISTER ============
   * Crée un nouveau compte utilisateur
   * @param {string} username
   * @param {string} email
   * @param {string} password
   * @param {string} passwordConfirm
   * @param {string} firstName
   * @returns {Promise<{success: boolean, user?: object, error?: string}>}
   */
  async register(username, email, password, passwordConfirm, firstName = '') {
    try {
      console.log('🆕 [AUTH] Registration attempt:', { username, email });

      // Validation côté client
      if (password !== passwordConfirm) {
        return {
          success: false,
          error: 'Passwords do not match'
        };
      }

      if (password.length < 8) {
        return {
          success: false,
          error: 'Password must be at least 8 characters'
        };
      }

      const response = await api.post('/auth/register/', {
        username,
        email,
        password,
        password_confirm: passwordConfirm,
        first_name: firstName
      });

      console.log('✅ [AUTH] Registration successful!', response.data);

      const { access, refresh, user } = response.data;

      // Stocker les tokens
      localStorage.setItem(ACCESS_TOKEN_KEY, access);
      localStorage.setItem(REFRESH_TOKEN_KEY, refresh);
      localStorage.setItem(USER_KEY, JSON.stringify(user));

      // Définir le header d'autorisation
      setAuthToken(access);

      return { 
        success: true, 
        user 
      };
    } catch (error) {
      const errorMsg = error.response?.data?.error || 
                       error.response?.data?.message || 
                       error.message || 
                       'Registration failed';

      console.error('❌ [AUTH] Registration failed:', errorMsg);

      return {
        success: false,
        error: errorMsg
      };
    }
  }

  /**
   * ============ LOGOUT ============
   * Déconnecte l'utilisateur
   * @returns {Promise<{success: boolean}>}
   */
  async logout() {
    try {
      console.log('🚪 [AUTH] Logout attempt...');

      const refreshToken = localStorage.getItem(REFRESH_TOKEN_KEY);

      // Essayer de signaler le logout au serveur
      if (refreshToken) {
        try {
          await api.post('/auth/logout/', {
            refresh: refreshToken
          });
        } catch (err) {
          console.warn('⚠️ [AUTH] Logout notification failed (will clear locally)', err.message);
        }
      }

      // Nettoyer les données locales
      this.clearAuth();

      console.log('✅ [AUTH] Logout successful!');

      return { success: true };
    } catch (error) {
      console.error('❌ [AUTH] Logout error:', error.message);
      // Nettoyer anyway
      this.clearAuth();
      return { success: true };
    }
  }

  /**
   * ============ REFRESH TOKEN ============
   * Rafraîchit le token d'accès
   * @returns {Promise<{success: boolean, access?: string}>}
   */
  async refreshToken() {
    try {
      console.log('🔄 [AUTH] Refreshing token...');

      const refreshToken = localStorage.getItem(REFRESH_TOKEN_KEY);

      if (!refreshToken) {
        console.warn('⚠️ [AUTH] No refresh token found');
        this.clearAuth();
        return { success: false };
      }

      const response = await api.post('/auth/refresh/', {
        refresh: refreshToken
      });

      console.log('✅ [AUTH] Token refreshed!');

      const { access } = response.data;

      localStorage.setItem(ACCESS_TOKEN_KEY, access);
      setAuthToken(access);

      return { 
        success: true, 
        access 
      };
    } catch (error) {
      console.error('❌ [AUTH] Token refresh failed:', error.message);
      this.clearAuth();
      return { success: false };
    }
  }

  /**
   * ============ GET CURRENT USER ============
   * Récupère les infos de l'utilisateur actuel
   * @returns {Promise<object|null>}
   */
  async getCurrentUser() {
    try {
      console.log('👤 [AUTH] Fetching current user...');

      const response = await api.get('/auth/me/');

      console.log('✅ [AUTH] Current user fetched!');

      return response.data;
    } catch (error) {
      console.error('❌ [AUTH] Get current user failed:', error.message);
      return null;
    }
  }

  /**
   * ============ TOKEN MANAGEMENT ============
   * Récupère le token JWT
   */
  getToken() {
    return localStorage.getItem(ACCESS_TOKEN_KEY);
  }

  /**
   * Récupère le refresh token
   */
  getRefreshToken() {
    return localStorage.getItem(REFRESH_TOKEN_KEY);
  }

  /**
   * Vérifie si l'utilisateur est authentifié
   */
  isAuthenticated() {
    return !!localStorage.getItem(ACCESS_TOKEN_KEY);
  }

  /**
   * Récupère les infos stockées de l'utilisateur
   */
  getUser() {
    const user = localStorage.getItem(USER_KEY);
    return user ? JSON.parse(user) : null;
  }

  /**
   * Met à jour les infos stockées de l'utilisateur
   */
  setUser(user) {
    localStorage.setItem(USER_KEY, JSON.stringify(user));
  }

  /**
   * ============ CLEANUP ============
   * Efface toutes les données d'authentification
   */
  clearAuth() {
    console.log('🗑️ [AUTH] Clearing auth data...');

    localStorage.removeItem(ACCESS_TOKEN_KEY);
    localStorage.removeItem(REFRESH_TOKEN_KEY);
    localStorage.removeItem(USER_KEY);

    clearAuthToken();
  }

  /**
   * ============ INITIALIZATION ============
   * Initialise le service d'auth (au chargement de l'app)
   */
  initialize() {
    console.log('⚙️ [AUTH] Initializing auth service...');

    const token = this.getToken();
    const user = this.getUser();

    if (token) {
      setAuthToken(token);
      console.log('✅ [AUTH] Token restored from storage');
    }

    if (user) {
      console.log(`✅ [AUTH] User restored: ${user.username}`);
    }

    return {
      isAuthenticated: !!token,
      user
    };
  }

  /**
   * ============ HELPER FUNCTIONS ============
   * Vérifie si le token est expiré
   */
  isTokenExpired() {
    try {
      const token = this.getToken();
      if (!token) return true;

      // Décoder le token (JWT = header.payload.signature)
      const parts = token.split('.');
      if (parts.length !== 3) return true;

      const payload = JSON.parse(atob(parts[1]));
      const expirationTime = payload.exp * 1000; // Convertir en ms

      return Date.now() >= expirationTime;
    } catch (error) {
      console.error('Error checking token expiry:', error);
      return true;
    }
  }

  /**
   * Récupère l'utilisateur actuel (depuis le token ou le serveur)
   */
  async ensureAuthenticated() {
    const isAuth = this.isAuthenticated();

    if (!isAuth) {
      return { authenticated: false, user: null };
    }

    // Vérifier si le token est expiré
    if (this.isTokenExpired()) {
      console.warn('⚠️ [AUTH] Token expired, attempting refresh...');
      const result = await this.refreshToken();
      if (!result.success) {
        return { authenticated: false, user: null };
      }
    }

    const user = this.getUser() || await this.getCurrentUser();
    return { 
      authenticated: true, 
      user 
    };
  }
}

// Exporter l'instance singleton
export default new AuthService();
